WITH scored AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, AVG(amount) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS amount_avg_2_prior, NTILE(4) OVER (PARTITION BY account_id ORDER BY amount, id) AS amount_bucket, COUNT(amount) OVER (PARTITION BY txn_type) AS txn_type_count_amount, AVG(amount) OVER (ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS amount_avg_7d, LAG(amount, 2, 0) OVER (PARTITION BY account_id ORDER BY txn_time, id) AS prev_amount FROM transactions) SELECT DATE_TRUNC('MONTH', txn_time) AS activity_month, MIN(txn_time) AS started_at, ROUND(AVG(amount_bucket), 2) AS avg_amount_bucket, COUNT(CASE WHEN txn_type = 'CREDIT' THEN 1 END) AS credit_count FROM scored GROUP BY DATE_TRUNC('MONTH', txn_time) ORDER BY credit_count
